BEGIN;
DO $$
DECLARE d uuid:=gen_random_uuid(); one_id uuid:=gen_random_uuid(); two_id uuid:=gen_random_uuid();
 m uuid:=gen_random_uuid(); next_match uuid:=gen_random_uuid(); expected timestamptz; rejected boolean;
 event_id bigint; division uuid;
BEGIN
 SELECT td.event_id,td.id INTO event_id,division FROM public.tournament_divisions td LIMIT 1;
 IF division IS NULL THEN RAISE EXCEPTION 'A fixture division is required'; END IF;
 INSERT INTO public.draws(id,event_id,division_id,draw_kind,format,status,scoring_rules) VALUES(d,event_id,division,'silver','knockout','published','{"sets_to_win":2}');
 INSERT INTO public.draw_entries(id,draw_id,team_name,player_one_name) VALUES(one_id,d,'Score test one','Score test one'),(two_id,d,'Score test two','Score test two');
 INSERT INTO public.draw_matches(id,draw_id,stage,round_code,round_label,round_number,bracket_position,status) VALUES(next_match,d,'knockout','final','Final',2,1,'pending');
 INSERT INTO public.draw_matches(id,draw_id,stage,round_code,round_label,round_number,bracket_position,entry_one_id,entry_two_id,status,winner_to_match_id,winner_to_slot) VALUES(m,d,'knockout','semi','Semifinals',1,1,one_id,two_id,'pending',next_match,1);
 SELECT updated_at INTO expected FROM public.draw_matches WHERE id=m;
 rejected:=false;
 BEGIN
  PERFORM public.native_record_draw_result(m,expected,jsonb_build_object('kind','played','sets',jsonb_build_array(jsonb_build_object('games',jsonb_build_array(6,5)),jsonb_build_object('games',jsonb_build_array(6,0)))));
 EXCEPTION WHEN others THEN rejected:=true; END;
 IF NOT rejected OR EXISTS(SELECT 1 FROM public.draw_match_sets WHERE match_id=m) OR (SELECT status FROM public.draw_matches WHERE id=m)<>'pending' THEN RAISE EXCEPTION 'Invalid score was not atomic'; END IF;
 rejected:=false;
 BEGIN PERFORM public.native_record_draw_result(m,expected,'{"kind":"live","sets":[{"games":[7,7]}]}'::jsonb); EXCEPTION WHEN others THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Invalid live 7-7 games accepted'; END IF;
 PERFORM public.native_record_draw_result(m,expected,'{"kind":"live","sets":[{"games":[6,1]},{"games":[3,2]}]}'::jsonb);
 IF (SELECT status FROM public.draw_matches WHERE id=m)<>'in_progress' OR (SELECT winner_entry_id IS NOT NULL FROM public.draw_matches WHERE id=m) OR (SELECT entry_one_id IS NOT NULL FROM public.draw_matches WHERE id=next_match) THEN RAISE EXCEPTION 'Live score advanced prematurely'; END IF;
 rejected:=false;
 BEGIN PERFORM public.native_record_draw_result(m,expected,'{"kind":"played","summary":[0,2],"sets":[]}'::jsonb); EXCEPTION WHEN others THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Stale update accepted'; END IF;
 SELECT updated_at INTO expected FROM public.draw_matches WHERE id=m;
 PERFORM public.native_record_draw_result(m,expected,'{"kind":"played","sets":[{"games":[6,7],"tiebreak":[7,9],"duration":65},{"games":[4,6]}]}'::jsonb);
 IF (SELECT winner_entry_id FROM public.draw_matches WHERE id=m)<>two_id OR (SELECT entry_one_id FROM public.draw_matches WHERE id=next_match)<>two_id OR (SELECT result_summary FROM public.draw_matches WHERE id=m)<>ARRAY[0,2]::smallint[] OR (SELECT duration_minutes FROM public.draw_match_sets WHERE match_id=m AND set_number=1)<>65 THEN RAISE EXCEPTION 'Detailed score or winner propagation failed'; END IF;
 -- Score-only corrections remain possible after later matches start.
 UPDATE public.draw_matches SET entry_two_id=one_id,status='in_progress' WHERE id=next_match;
 SELECT updated_at INTO expected FROM public.draw_matches WHERE id=m;
 rejected:=false;
 BEGIN PERFORM public.native_record_draw_result(m,expected,'{"kind":"played","summary":[0,2],"sets":[]}'::jsonb); EXCEPTION WHEN others THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Correction without a reason accepted'; END IF;
 PERFORM public.native_record_draw_result(m,expected,'{"kind":"played","summary":[0,2],"sets":[],"reason":"Corrected transcription"}'::jsonb);
 IF NOT EXISTS(SELECT 1 FROM public.draw_match_audit WHERE match_id=m AND action='score_corrected' AND after_state->>'reason'='Corrected transcription') OR (SELECT entry_one_id FROM public.draw_matches WHERE id=next_match)<>two_id THEN RAISE EXCEPTION 'Correction audit or unchanged route failed'; END IF;
 SELECT updated_at INTO expected FROM public.draw_matches WHERE id=m;
 rejected:=false;
 BEGIN PERFORM public.native_record_draw_result(m,expected,'{"kind":"played","summary":[2,0],"sets":[],"reason":"Wrong winner"}'::jsonb); EXCEPTION WHEN others THEN rejected:=true; END;
 IF NOT rejected OR (SELECT winner_entry_id FROM public.draw_matches WHERE id=m)<>two_id THEN RAISE EXCEPTION 'A changed winner corrupted an active dependent match'; END IF;
 UPDATE public.draws SET status='completed' WHERE id=d;
 PERFORM public.native_record_draw_result(m,expected,'{"kind":"played","sets":[{"games":[2,6]},{"games":[3,6]}],"reason":"Corrected set games"}'::jsonb);
 IF (SELECT status FROM public.draws WHERE id=d)<>'completed' OR (SELECT entry_one_games FROM public.draw_match_sets WHERE match_id=m AND set_number=1)<>2 THEN RAISE EXCEPTION 'Completed draw score correction failed'; END IF;
 SELECT updated_at INTO expected FROM public.draw_matches WHERE id=m;
 rejected:=false;
 BEGIN PERFORM public.native_record_draw_result(m,expected,'{"kind":"played","summary":[2,0],"sets":[],"reason":"Wrong winner"}'::jsonb); EXCEPTION WHEN others THEN rejected:=true; END;
 IF NOT rejected OR (SELECT winner_entry_id FROM public.draw_matches WHERE id=m)<>two_id THEN RAISE EXCEPTION 'Completed draw winner changed without points review'; END IF;
 UPDATE public.draws SET status='published' WHERE id=d;
 INSERT INTO public.draw_matches(id,draw_id,stage,round_code,round_label,round_number,bracket_position,entry_one_id,entry_two_id,status) VALUES(gen_random_uuid(),d,'placement','test','Test placement',1,1,one_id,two_id,'pending') RETURNING id,updated_at INTO m,expected;
 PERFORM public.native_record_draw_result(m,expected,'{"kind":"played","summary":[2,1],"sets":[]}'::jsonb);
 IF (SELECT result_summary FROM public.draw_matches WHERE id=m)<>ARRAY[2,1]::smallint[] OR EXISTS(SELECT 1 FROM public.draw_match_sets WHERE match_id=m) THEN RAISE EXCEPTION 'Summary-only score failed'; END IF;
 INSERT INTO public.draw_matches(id,draw_id,stage,round_code,round_label,round_number,bracket_position,entry_one_id,entry_two_id,status) VALUES(gen_random_uuid(),d,'placement','test','Test placement',1,2,one_id,two_id,'pending') RETURNING id,updated_at INTO m,expected;
 PERFORM public.native_record_draw_result(m,expected,jsonb_build_object('kind','retirement','winner',two_id,'sets','[]'::jsonb));
 IF (SELECT status FROM public.draw_matches WHERE id=m)<>'retired' OR (SELECT winner_entry_id FROM public.draw_matches WHERE id=m)<>two_id THEN RAISE EXCEPTION 'Retirement failed'; END IF;
 IF has_function_privilege('anon','public.native_record_draw_result(uuid,timestamptz,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Anonymous callers can enter results'; END IF;
END $$;
SELECT 'Atomic scores, live progress, summaries, retirements, metadata, advancement, audited corrections, completed-draw edits and winner-change protection passed' AS verification;
ROLLBACK;
